  "design_rules": {
    "parent_order_split": "买家一次下单按商家拆单：1 parent_order → N order（每商家一单）。支付模块以 parent_order 为单位对接，payment_ref_no 引用支付模块单号",
    "order_status_enum": "order_status 枚举：paid(已付款) / shipped(已发货) / completed(交易完成) / cancelled(已取消)。订单在支付成功后创建，起始状态即 paid。发货状态由 order_package.package_status 管理，不在 order 层细分",
    "item_status_enum": "item_status 枚举：pending(待发货) / refunding(退款中) / refunded(已退款) / shipped(已发货) / received(已签收) / cancelled(已取消)",
    "package_status_enum": "package_status 枚举：pending(待发货) / shipped(已发货) / received(已签收)",
    "payment_status_enum": "payment_status 枚举：paid(已支付)。parent_order 仅在支付成功后创建，起始状态即 paid。后续退款可扩展 partially_refunded / refunded",
    "refund_status_enum": "refund_status 枚举：pending(待处理) / processing(处理中) / completed(已完成) / rejected(已拒绝)",
    "refund_type_enum": "refund_type 枚举：pre_shipment(发货前退款)。后续扩展退货退款时新增类型",
    "request_channel_enum": "request_channel 枚举：email(邮件)。后续扩展自助申请时新增 app / web",
    "operator_type_enum": "operator_type 枚举：admin(运营人员) / system(系统自动)。参考库存模块 inventory_ledger 的操作人设计模式",
    "address_snapshot": "订单创建时快照收货地址（address_id UUID + 10 个快照字段）。字段命名对齐地址模块：address_line1/state_province/postal_code。recipient_first_name + last_name 拆分存储（报关需要），recipient_name 冗余拼接用于展示。地址模块后续更新不影响已有订单",
    "price_snapshot": "order_item 在创建时快照 listing_price 为 unit_price。listing 价格变动不影响已有订单",
    "condition_snapshot": "order_item 快照 product_inspection.grade 为 condition_grade",
    "package_boundary": "订单模块用 order_package 记录「发了几个包裹」，物流模块管「怎么发」（承运商/追踪/轨迹）。跨模块关联：order_no = shipments.business_order_no（按订单维度），tracking_no = shipments.tracking_no（按包裹维度）。物流模块是独立信息服务，不直接引用订单实体",
    "order_completion_rule": "订单完成判定：所有 order_package.package_status 为 received → 订单标记 completed",
    "refund_blocks_shipping": "退款审批通过后，order_item.item_status 变为 refunding → 该商品不得发货",
    "package_simplification": "订单 = 履约作业单元（按商家拆单，未来按仓库再拆）。多包裹仅因物理尺寸约束，不做包裹-商品映射。买家视角只关心「订单有几个包裹，追踪号是什么」",
    "checkout_status_enum": "checkout_status 枚举：pending(进行中) / converted(已转化为订单) / expired(超时弃单)",
    "checkout_to_order_flow": "完整数据流：购物车 → 进入结算页创建 checkout_session(pending) + items 快照 → 填地址/确认商品 → 提交/去支付 → 支付成功 → checkout_session(converted) + 创建 parent_order + order + order_item",
    "checkout_abandonment": "弃单规则：checkout_session 超时未完成支付 → 标记 expired。恢复机制：recovery_token 生成唯一恢复链接，买家点击可回到结算页。恢复时需检查商品是否仍可购买（二手一物一件，可能已售出）",
    "cart_to_order_flow": "购物车到订单数据流：cart_item.listing_id → checkout_session_item（快照价格）→ 支付成功 → order_item（product_id + listing_id + 快照价格/成色/名称/图片）",
    "financial_model": "订单金额公式：order 实际收款 = subtotal_amount + shipping_fee + tax_amount。subtotal_amount = SUM(order_item.item_total)。parent_order.total_amount = SUM(各 order 的实际收款)。后续扩展优惠时：实际收款 = subtotal_amount + shipping_fee - discount_amount + tax_amount",
    "tax_rule": "tax_amount 按收货地址所在州的税率计算（美国各州税率不同）。税费计算在结算时由应用层完成，订单只记录结果",
    "currency_rule": "同一订单内所有金额使用相同 currency_code",
    "user_id_redundancy": "parent_order.user_id 和 order.user_id 均冗余存储买家ID，源头在 checkout_session.user_id，避免多层 join",
    "merchant_id_vs_seller_id": "商品模块用 seller_id 引用 merchants.id（卖方语境），订单模块用 merchant_id 引用同一实体（商家语境）。同一 FK 目标，不同业务语义"
  }
}
